package dev.redstoneengineering.block;
import com.mojang.serialization.MapCodec;import dev.redstoneengineering.*;import dev.redstoneengineering.physics.RadioKernel;import net.minecraft.core.*;import net.minecraft.network.chat.Component;import net.minecraft.server.level.ServerLevel;import net.minecraft.util.RandomSource;import net.minecraft.world.*;import net.minecraft.world.entity.player.Player;import net.minecraft.world.level.*;import net.minecraft.world.level.block.Block;import net.minecraft.world.level.block.state.*;import net.minecraft.world.level.block.state.properties.IntegerProperty;import net.minecraft.world.phys.BlockHitResult;
/** Radio receiver: outputs decoded payload; diagnostics expose quality and collision separately. */
public class RadioReceiverBlock extends PassiveDirectionalSignalBlock{public static final IntegerProperty CHANNEL=IntegerProperty.create("channel",0,3);public RadioReceiverBlock(Properties p){super(p);registerDefaultState(defaultBlockState().setValue(CHANNEL,0));}@Override public MapCodec<RadioReceiverBlock> codec(){return RedstoneEngineering.RADIO_RECEIVER_CODEC.value();}@Override protected void createBlockStateDefinition(StateDefinition.Builder<Block,BlockState>b){super.createBlockStateDefinition(b);b.add(CHANNEL);}@Override protected int computeOutput(Level l,BlockPos p,BlockState s){return RadioKernel.receivePacket(l,p,s.getValue(CHANNEL)).value();}@Override protected void onPlace(BlockState s,Level l,BlockPos p,BlockState o,boolean m){super.onPlace(s,l,p,o,m);if(l instanceof ServerLevel sl)sl.scheduleTick(p,this,5);}@Override protected void tick(BlockState s,ServerLevel l,BlockPos p,RandomSource r){updateOutput(l,p,s,outputValue(l,p,s));l.scheduleTick(p,this,5);}@Override protected InteractionResult useWithoutItem(BlockState s,Level l,BlockPos p,Player pl,BlockHitResult h){if(!l.isClientSide){int c=(s.getValue(CHANNEL)+1)%4;BlockState ns=s.setValue(CHANNEL,c);l.setBlock(p,ns,Block.UPDATE_CLIENTS);var rx=RadioKernel.receivePacket(l,p,c);pl.displayClientMessage(Component.literal("Radio RX ch="+c+" payload="+rx.value()+"/15 quality="+rx.quality()+"% drivers="+rx.drivers()+" adjacentInterference="+rx.interference()+" obstacles="+rx.obstacles()+" latency≈"+rx.latencyTicks()+"t "+(rx.collision()?"COLLISION":rx.valid()?"VALID":"UNDECODABLE")),true);}return InteractionResult.sidedSuccess(l.isClientSide);}}
